1	/* Equation numbers refer to Knueven, Ostrowski, Watson, "On Mixed Integer
2	 * Programming Formulations for the Unit Commitment Problem". NOTES.md explains
3	 * each place where the code differs from the printed text. */
4	#include "model.h"
5	
6	#include <math.h>
7	#include <stdio.h>
8	#include <stdlib.h>
9	#include <string.h>
10	
11	#define COEF_EPS 1e-11
12	
13	static double pos(double x) { return x > 0 ? x : 0; }
14	static int imin(int a, int b) { return a < b ? a : b; }
15	
16	typedef struct {
17	    /* columns */
18	    int ncol, capcol;
19	    double *obj, *lb, *ub;
20	    char *vtype;
21	    /* rows, in compressed form */
22	    int nrow, caprow, nnz, capnz;
23	    int *beg, *ind;
24	    double *val, *rhs;
25	    char *sense;
26	    int relax;
27	} Builder;
28	
29	static void *xrealloc(void *p, size_t n) {
30	    void *q = realloc(p, n ? n : 1);
31	    if (!q) { fprintf(stderr, "out of memory\n"); exit(1); }
32	    return q;
33	}
34	
35	static int add_col(Builder *b, double obj, double lb, double ub, char type) {
36	    if (b->ncol == b->capcol) {
37	        b->capcol = b->capcol ? 2 * b->capcol : 4096;
38	        b->obj = xrealloc(b->obj, (size_t)b->capcol * sizeof(double));
39	        b->lb = xrealloc(b->lb, (size_t)b->capcol * sizeof(double));
40	        b->ub = xrealloc(b->ub, (size_t)b->capcol * sizeof(double));
41	        b->vtype = xrealloc(b->vtype, (size_t)b->capcol);
42	    }
43	    b->obj[b->ncol] = obj;
44	    b->lb[b->ncol] = lb;
45	    b->ub[b->ncol] = ub;
46	    b->vtype[b->ncol] = type;
47	    return b->ncol++;
48	}
49	
50	static int add_binary(Builder *b, double obj, double lb, double ub) {
51	    return add_col(b, obj, lb, ub, b->relax ? GRB_CONTINUOUS : GRB_BINARY);
52	}
53	
54	static int add_cont(Builder *b, double obj) {
55	    return add_col(b, obj, 0.0, GRB_INFINITY, GRB_CONTINUOUS);
56	}
57	
58	static void row_begin(Builder *b) {
59	    if (b->nrow == b->caprow) {
60	        b->caprow = b->caprow ? 2 * b->caprow : 4096;
61	        b->beg = xrealloc(b->beg, (size_t)b->caprow * sizeof(int));
62	        b->rhs = xrealloc(b->rhs, (size_t)b->caprow * sizeof(double));
63	        b->sense = xrealloc(b->sense, (size_t)b->caprow);
64	    }
65	    b->beg[b->nrow] = b->nnz;
66	}
67	
68	static void row_add(Builder *b, int col, double coef) {
69	    if (fabs(coef) < COEF_EPS) return;
70	    if (b->nnz == b->capnz) {
71	        b->capnz = b->capnz ? 2 * b->capnz : 65536;
72	        b->ind = xrealloc(b->ind, (size_t)b->capnz * sizeof(int));
73	        b->val = xrealloc(b->val, (size_t)b->capnz * sizeof(double));
74	    }
75	    b->ind[b->nnz] = col;
76	    b->val[b->nnz] = coef;
77	    b->nnz++;
78	}
79	
80	static void row_end(Builder *b, char sense, double rhs) {
81	    b->sense[b->nrow] = sense;
82	    b->rhs[b->nrow] = rhs;
83	    b->nrow++;
84	}
85	
86	static int *new_index(int T) {
87	    int *a = xrealloc(NULL, (size_t)(T + 2) * sizeof(int));
88	    for (int t = 0; t < T + 2; t++) a[t] = -1;
89	    return a;
90	}
91	
92	/* Everything needed to write coef*v(tau) or coef*w(tau) for any tau: inside the
93	 * horizon it is a variable, before it a known value, after it zero (Section 3). */
94	typedef struct {
95	    Builder *b;
96	    const Gen *g;
97	    const GenVars *x;
98	    int T, no_hist_v;
99	    double rhs;   /* accumulates the constants of the current <= row */
100	} RowCtx;
101	
102	static void add_v(RowCtx *c, int tau, double coef) {
103	    if (tau > c->T) return;
104	    if (tau >= 1) row_add(c->b, c->x->v[tau], coef);
105	    else if (!c->no_hist_v && gen_hist_v(c->g, tau)) c->rhs -= coef;
106	}
107	
108	static void add_w(RowCtx *c, int tau, double coef) {
109	    if (tau > c->T) return;
110	    if (tau >= 1) row_add(c->b, c->x->w[tau], coef);
111	    else if (gen_hist_w(c->g, tau)) c->rhs -= coef;
112	}
113	
114	/* First period with a row (4) or (5), given the minimum time. */
115	static int updown_first(int min_time, int T, UpDownMode mode) {
116	    if (mode == UPDOWN_ALL_PERIODS) return 1;
117	    if (mode == UPDOWN_PRINTED) return min_time;
118	    return imin(min_time, T);
119	}
120	
121	/* (2), (3) as bounds on u, (4), (5). */
122	static void add_updown(Builder *b, const Gen *g, const GenVars *x, int T, UpDownMode mode) {
123	    for (int t = 1; t <= T; t++) {
124	        row_begin(b);
125	        row_add(b, x->u[t], 1.0);
126	        if (t > 1) row_add(b, x->u[t - 1], -1.0);
127	        row_add(b, x->v[t], -1.0);
128	        row_add(b, x->w[t], 1.0);
129	        row_end(b, GRB_EQUAL, t == 1 ? (double)g->on0 : 0.0);
130	    }
131	    for (int t = updown_first(g->ut, T, mode); t <= T; t++) {
132	        double hist = 0;
133	        row_begin(b);
134	        for (int i = t - g->ut + 1; i <= t; i++) {
135	            if (i >= 1) row_add(b, x->v[i], 1.0);
136	            else if (gen_hist_v(g, i)) hist += 1.0;
137	        }
138	        row_add(b, x->u[t], -1.0);
139	        row_end(b, GRB_LESS_EQUAL, -hist);
140	    }
141	    for (int t = updown_first(g->dt, T, mode); t <= T; t++) {
142	        double hist = 0;
143	        row_begin(b);
144	        for (int i = t - g->dt + 1; i <= t; i++) {
145	            if (i >= 1) row_add(b, x->w[i], 1.0);
146	            else if (gen_hist_w(g, i)) hist += 1.0;
147	        }
148	        row_add(b, x->u[t], 1.0);
149	        row_end(b, GRB_LESS_EQUAL, 1.0 - hist);
150	    }
151	}
152	
153	/* (17), (23), (38), (40), (41), stated in the p', pbar' variables by (12)-(15). */
154	static void add_generation_limits(Builder *b, const Gen *g, const GenVars *x, int T, const ModelOptions *o) {
155	    const double range = g->pmax - g->pmin;
156	    for (int t = 1; t <= T; t++) {
157	        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };
158	
159	        /* (17) */
160	        row_begin(b);
161	        row_add(b, x->pp[t], 1.0);
162	        row_add(b, x->pa[t], -1.0);
163	        row_end(b, GRB_LESS_EQUAL, 0.0);
164	
165	        if (g->ut == 1) {
166	            /* (23a) */
167	            row_begin(b);
168	            c.rhs = 0;
169	            row_add(b, x->pa[t], 1.0);
170	            row_add(b, x->u[t], -range);
171	            add_v(&c, t, g->pmax - g->su);
172	            add_w(&c, t + 1, pos(g->su - g->sd));
173	            row_end(b, GRB_LESS_EQUAL, c.rhs);
174	            /* (23b) */
175	            row_begin(b);
176	            c.rhs = 0;
177	            row_add(b, x->pa[t], 1.0);
178	            row_add(b, x->u[t], -range);
179	            add_w(&c, t + 1, g->pmax - g->sd);
180	            add_v(&c, t, pos(g->sd - g->su));
181	            row_end(b, GRB_LESS_EQUAL, c.rhs);
182	        }
183	
184	        /* (38) */
185	        row_begin(b);
186	        c.rhs = 0;
187	        row_add(b, x->pa[t], 1.0);
188	        row_add(b, x->u[t], -range);
189	        add_w(&c, t + 1, g->pmax - g->sd);
190	        for (int i = 0; i <= imin(g->ut - 2, g->tru); i++)
191	            add_v(&c, t - i, g->pmax - g->su - i * g->ru);
192	        row_end(b, GRB_LESS_EQUAL, c.rhs);
193	
194	        /* (40) */
195	        if (g->tru > g->ut - 2) {
196	            row_begin(b);
197	            c.rhs = 0;
198	            row_add(b, x->pa[t], 1.0);
199	            row_add(b, x->u[t], -range);
200	            for (int i = 0; i <= imin(g->ut - 1, g->tru); i++)
201	                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
202	            row_end(b, GRB_LESS_EQUAL, c.rhs);
203	        }
204	
205	        /* (41): K^SD from (37); the printed K^SU refers to itself and is read with
206	         * [K^SD]^+ (NOTES.md). The left side is p', not pbar'. */
207	        int ksd = imin(imin(g->trd, g->ut - 1), T - t - 1);
208	        if (ksd > 0) {
209	            int ksu = imin(imin(g->tru, g->ut - 2 - ksd), t - 1);
210	            row_begin(b);
211	            c.rhs = 0;
212	            row_add(b, x->pp[t], 1.0);
213	            row_add(b, x->u[t], -range);
214	            for (int i = 0; i <= ksd; i++)
215	                add_w(&c, t + 1 + i, g->pmax - g->sd - i * g->rd);
216	            for (int i = 0; i <= ksu; i++)
217	                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
218	            if (ksu < g->tru) {
219	                double a = g->su + (ksu + 1) * g->ru;
220	                double coef = 0;
221	                if (o->tail == TAIL_PRINTED) coef = pos(a - (g->sd + g->trd * g->rd));
222	                else if (o->tail == TAIL_CORRECTED) coef = pos((g->sd + ksd * g->rd) - a);
223	                add_v(&c, t - (ksu + 1), coef);
224	            }
225	            row_end(b, GRB_LESS_EQUAL, c.rhs);
226	        }
227	    }
228	}
229	
230	/* (35), (36). */
231	static void add_ramps(Builder *b, const Gen *g, const GenVars *x, int T) {
232	    const double pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
233	    for (int t = 1; t <= T; t++) {
234	        row_begin(b);
235	        row_add(b, x->pa[t], 1.0);
236	        if (t > 1) row_add(b, x->pp[t - 1], -1.0);
237	        row_add(b, x->v[t], -(g->su - g->pmin - g->ru));
238	        row_add(b, x->u[t], -g->ru);
239	        row_end(b, GRB_LESS_EQUAL, t == 1 ? pp0 : 0.0);
240	
241	        double rhs = 0;
242	        row_begin(b);
243	        if (t > 1) {
244	            row_add(b, x->pp[t - 1], 1.0);
245	            row_add(b, x->u[t - 1], -g->rd);
246	        } else {
247	            rhs = g->rd * g->on0 - pp0;
248	        }
249	        row_add(b, x->pp[t], -1.0);
250	        row_add(b, x->w[t], -(g->sd - g->pmin - g->rd));
251	        row_end(b, GRB_LESS_EQUAL, rhs);
252	    }
253	}
254	
255	/* C^v(l) or C^w(l) of (46): limit is SU or SD. */
256	static double seg_coef(const Gen *g, int l, double limit) {
257	    if (g->pw[l] <= limit) return 0.0;
258	    if (g->pw[l - 1] < limit) return g->pw[l] - limit;
259	    return g->pw[l] - g->pw[l - 1];
260	}
261	
262	/* (43), (46) or (48); (44) is substituted into the objective. */
263	static void add_piecewise(Builder *b, const Gen *g, const GenVars *x, int **pl, int T, const ModelOptions *o) {
264	    for (int t = 1; t <= T; t++) {
265	        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };
266	        row_begin(b);
267	        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
268	        row_add(b, x->pp[t], -1.0);
269	        row_end(b, GRB_EQUAL, 0.0);
270	
271	        for (int l = 1; l <= g->nseg; l++) {
272	            double d = g->pw[l] - g->pw[l - 1];
273	            double cv = seg_coef(g, l, g->su), cw = seg_coef(g, l, g->sd);
274	            if (g->ut > 1) {
275	                /* (46) */
276	                row_begin(b);
277	                row_add(b, pl[l][t], 1.0);
278	                row_add(b, x->u[t], -d);
279	                add_v(&c, t, cv);
280	                add_w(&c, t + 1, cw);
281	                row_end(b, GRB_LESS_EQUAL, 0.0);
282	            } else {
283	                /* (48). The printed operands of [.]^+ are reversed relative to (23);
284	                 * see NOTES.md. */
285	                double to_w = o->pw48_printed ? pos(cv - cw) : pos(cw - cv);
286	                double to_v = o->pw48_printed ? pos(cw - cv) : pos(cv - cw);
287	                row_begin(b);
288	                row_add(b, pl[l][t], 1.0);
289	                row_add(b, x->u[t], -d);
290	                add_v(&c, t, cv);
291	                add_w(&c, t + 1, to_w);
292	                row_end(b, GRB_LESS_EQUAL, 0.0);
293	                row_begin(b);
294	                row_add(b, pl[l][t], 1.0);
295	                row_add(b, x->u[t], -d);
296	                add_w(&c, t + 1, cw);
297	                add_v(&c, t, to_v);
298	                row_end(b, GRB_LESS_EQUAL, 0.0);
299	            }
300	        }
301	    }
302	}
303	
304	/* A basic physical model built from (18), (19), (24), (25), (43), (42): the same
305	 * integer feasible set as T, with none of T's strengthening. Used only to test T. */
306	static void add_base_physical(Builder *b, const Gen *g, const GenVars *x, int **pl, int T) {
307	    const double range = g->pmax - g->pmin, pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
308	    for (int t = 1; t <= T; t++) {
309	        RowCtx c = { b, g, x, T, 1, 0.0 };
310	        row_begin(b);
311	        row_add(b, x->pp[t], 1.0);
312	        row_add(b, x->pa[t], -1.0);
313	        row_end(b, GRB_LESS_EQUAL, 0.0);
314	        row_begin(b);
315	        row_add(b, x->pa[t], 1.0);
316	        row_add(b, x->u[t], -range);
317	        add_w(&c, t + 1, g->pmax - g->sd);
318	        row_end(b, GRB_LESS_EQUAL, 0.0);
319	
320	        /* (24) */
321	        double rhs = 0;
322	        row_begin(b);
323	        row_add(b, x->pa[t], 1.0);
324	        row_add(b, x->u[t], g->pmin);
325	        row_add(b, x->v[t], -g->su);
326	        if (t > 1) {
327	            row_add(b, x->pp[t - 1], -1.0);
328	            row_add(b, x->u[t - 1], -g->pmin - g->ru);
329	        } else {
330	            rhs = pp0 + g->on0 * (g->pmin + g->ru);
331	        }
332	        row_end(b, GRB_LESS_EQUAL, rhs);
333	        /* (25) */
334	        rhs = 0;
335	        row_begin(b);
336	        if (t > 1) {
337	            row_add(b, x->pp[t - 1], 1.0);
338	            row_add(b, x->u[t - 1], g->pmin);
339	        } else {
340	            rhs = -pp0 - g->on0 * g->pmin;
341	        }
342	        row_add(b, x->pp[t], -1.0);
343	        row_add(b, x->u[t], -g->pmin - g->rd);
344	        row_add(b, x->w[t], -g->sd);
345	        row_end(b, GRB_LESS_EQUAL, rhs);
346	
347	        row_begin(b);
348	        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
349	        row_add(b, x->pp[t], -1.0);
350	        row_end(b, GRB_EQUAL, 0.0);
351	        for (int l = 1; l <= g->nseg; l++) {
352	            row_begin(b);
353	            row_add(b, pl[l][t], 1.0);
354	            row_add(b, x->u[t], -(g->pw[l] - g->pw[l - 1]));
355	            row_end(b, GRB_LESS_EQUAL, 0.0);
356	        }
357	    }
358	}
359	
360	/* Variables x(t',t) of (59)-(61), for shut-down at t' and start-up at t with
361	 * DT <= t-t' <= TC-1, and the rows (59), (60). Their objective coefficients are
362	 * those of (61) after substitution into (69). Only one historical shut-down
363	 * exists: t' = 1-down0 for a unit that is off at period 0. */
364	static void add_startup(Builder *b, const Gen *g, const GenVars *x, int T) {
365	    const int S = g->ncat;
366	    if (S < 2 || g->tc <= g->dt) return;
367	    const double cold = g->scost[S - 1];
368	    int *xh = new_index(T);
369	    int *xm = xrealloc(NULL, (size_t)(T + 2) * (size_t)(T + 2) * sizeof(int));
370	    for (int k = 0; k < (T + 2) * (T + 2); k++) xm[k] = -1;
371	
372	#define XM(tp, t) xm[(tp) * (T + 2) + (t)]
373	    for (int t = 1; t <= T; t++) {
374	        for (int tp = t - g->tc + 1; tp <= t - g->dt; tp++) {
375	            if (tp < 1 && !gen_hist_w(g, tp)) continue;
376	            int s = 0;
377	            while (s + 1 < S && g->lag[s + 1] <= t - tp) s++;
378	            int col = add_binary(b, -(cold - g->scost[s]), 0.0, 1.0);
379	            if (tp >= 1) XM(tp, t) = col;
380	            else xh[t] = col;
381	        }
382	    }
383	    /* (59) */
384	    for (int t = 1; t <= T; t++) {
385	        int any = 0;
386	        row_begin(b);
387	        for (int tp = 1; tp < t; tp++)
388	            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
389	        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
390	        if (any) {
391	            row_add(b, x->v[t], -1.0);
392	            row_end(b, GRB_LESS_EQUAL, 0.0);
393	        } else {
394	            b->nnz = b->beg[b->nrow];
395	        }
396	    }
397	    /* (60) */
398	    for (int tp = 1; tp <= T; tp++) {
399	        int any = 0;
400	        row_begin(b);
401	        for (int t = tp + 1; t <= T; t++)
402	            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
403	        if (any) {
404	            row_add(b, x->w[tp], -1.0);
405	            row_end(b, GRB_LESS_EQUAL, 0.0);
406	        } else {
407	            b->nnz = b->beg[b->nrow];
408	        }
409	    }
410	    /* (60) at the historical shut-down, where w = 1 */
411	    int any = 0;
412	    row_begin(b);
413	    for (int t = 1; t <= T; t++)
414	        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
415	    if (any) row_end(b, GRB_LESS_EQUAL, 1.0);
416	    else b->nnz = b->beg[b->nrow];
417	#undef XM
418	    free(xm);
419	    free(xh);
420	}
