422	void model_default_options(ModelOptions *o) {
423	    memset(o, 0, sizeof *o);
424	    o->tail = TAIL_CORRECTED;
425	    o->only_gen = -1;
426	}
427	
428	int model_apply_variant(ModelOptions *o, const char *name) {
429	    if (!strcmp(name, "tail-none")) o->tail = TAIL_NONE;
430	    else if (!strcmp(name, "tail-printed")) o->tail = TAIL_PRINTED;
431	    else if (!strcmp(name, "tail-corrected")) o->tail = TAIL_CORRECTED;
432	    else if (!strcmp(name, "pw48-printed")) o->pw48_printed = 1;
433	    else if (!strcmp(name, "pw48-corrected")) o->pw48_printed = 0;
434	    else if (!strcmp(name, "reserve-printed")) o->reserve_printed = 1;
435	    else if (!strcmp(name, "reserve-renewables")) o->reserve_printed = 0;
436	    else if (!strcmp(name, "updown-clamped")) o->updown = UPDOWN_CLAMPED;
437	    else if (!strcmp(name, "updown-printed")) o->updown = UPDOWN_PRINTED;
438	    else if (!strcmp(name, "updown-all-periods")) o->updown = UPDOWN_ALL_PERIODS;
439	    else if (!strcmp(name, "no-hist-v")) o->no_hist_v = 1;
440	    else if (!strcmp(name, "base")) o->base_model = 1;
441	    else return 0;
442	    return 1;
443	}
444	
445	int model_build(GRBenv *env, const Instance *in, const ModelOptions *o,
446	                GRBmodel **model_out, VarMap **map_out) {
447	    const int T = in->T;
448	    Builder bb, *b = &bb;
449	    memset(b, 0, sizeof *b);
450	    b->relax = o->relax;
451	
452	    VarMap *m = xrealloc(NULL, sizeof *m);
453	    memset(m, 0, sizeof *m);
454	    m->T = T;
455	    m->ngen = in->ngen;
456	    m->gen = xrealloc(NULL, (size_t)in->ngen * sizeof *m->gen);
457	    memset(m->gen, 0, (size_t)in->ngen * sizeof *m->gen);
458	
459	    for (int gi = 0; gi < in->ngen; gi++) {
460	        if (o->only_gen >= 0 && gi != o->only_gen) continue;
461	        const Gen *g = &in->gen[gi];
462	        GenVars *x = &m->gen[gi];
463	        x->u = new_index(T);
464	        x->v = new_index(T);
465	        x->w = new_index(T);
466	        x->pp = new_index(T);
467	        x->pa = new_index(T);
468	        int **pl = xrealloc(NULL, (size_t)(g->nseg + 1) * sizeof *pl);
469	        for (int l = 1; l <= g->nseg; l++) pl[l] = new_index(T);
470	
471	        for (int t = 1; t <= T; t++) {
472	            double lb = 0.0, ub = 1.0;
473	            if (t <= imin(g->need_up, T)) lb = 1.0;          /* (3a) */
474	            if (t <= imin(g->need_down, T)) ub = 0.0;        /* (3b) */
475	            if (g->must_run) lb = 1.0;
476	            x->u[t] = add_binary(b, g->cr, lb, ub);
477	            x->v[t] = add_binary(b, g->scost[g->ncat - 1], 0.0, 1.0);
478	            x->w[t] = add_binary(b, 0.0, 0.0, 1.0);          /* C^w = 0 in (62) */
479	            x->pp[t] = add_cont(b, 0.0);
480	            x->pa[t] = add_cont(b, 0.0);
481	            for (int l = 1; l <= g->nseg; l++) pl[l][t] = add_cont(b, g->slope[l]);
482	        }
483	
484	        add_updown(b, g, x, T, o->base_model ? UPDOWN_ALL_PERIODS : o->updown);
485	        if (o->base_model) {
486	            add_base_physical(b, g, x, pl, T);
487	        } else {
488	            add_generation_limits(b, g, x, T, o);
489	            add_ramps(b, g, x, T);
490	            add_piecewise(b, g, x, pl, T, o);
491	        }
492	        add_startup(b, g, x, T);
493	
494	        for (int l = 1; l <= g->nseg; l++) free(pl[l]);
495	        free(pl);
496	    }
497	
498	    if (o->only_gen < 0) {
499	        m->pw = new_index(T);
500	        m->splus = new_index(T);
501	        m->sminus = new_index(T);
502	        m->sr = new_index(T);
503	        for (int t = 1; t <= T; t++) {
504	            m->pw[t] = add_col(b, 0.0, in->ren_min[t], in->ren_max[t], GRB_CONTINUOUS);  /* (63) */
505	            m->splus[t] = add_cont(b, UC_C_LP);    /* (66) */
506	            m->sminus[t] = add_cont(b, UC_C_LP);
507	            m->sr[t] = add_cont(b, UC_C_RP);
508	        }
509	        for (int t = 1; t <= T; t++) {
510	            /* (65) with one bus: (64) is dropped and the flow sums are empty. */
511	            row_begin(b);
512	            for (int gi = 0; gi < in->ngen; gi++) {
513	                row_add(b, m->gen[gi].pp[t], 1.0);
514	                row_add(b, m->gen[gi].u[t], in->gen[gi].pmin);
515	            }
516	            row_add(b, m->pw[t], 1.0);
517	            row_add(b, m->splus[t], 1.0);
518	            row_add(b, m->sminus[t], -1.0);
519	            row_end(b, GRB_EQUAL, in->demand[t]);
520	
521	            /* (67), by default with the renewable term (NOTES.md). */
522	            row_begin(b);
523	            for (int gi = 0; gi < in->ngen; gi++) {
524	                row_add(b, m->gen[gi].pa[t], 1.0);
525	                row_add(b, m->gen[gi].u[t], in->gen[gi].pmin);
526	            }
527	            if (!o->reserve_printed) row_add(b, m->pw[t], 1.0);
528	            row_add(b, m->sr[t], 1.0);
529	            row_end(b, GRB_GREATER_EQUAL, in->demand[t] + in->reserve[t]);
530	        }
531	    }
532	
533	    GRBmodel *model = NULL;
534	    int err = GRBnewmodel(env, &model, "uc_T", b->ncol, b->obj, b->lb, b->ub, b->vtype, NULL);
535	    if (!err) err = GRBsetintattr(model, GRB_INT_ATTR_MODELSENSE, GRB_MINIMIZE);
536	    if (!err) err = GRBaddconstrs(model, b->nrow, b->nnz, b->beg, b->ind, b->val, b->sense, b->rhs, NULL);
537	    if (!err) err = GRBupdatemodel(model);
538	    m->numvars = b->ncol;
539	
540	    free(b->obj); free(b->lb); free(b->ub); free(b->vtype);
541	    free(b->beg); free(b->ind); free(b->val); free(b->rhs); free(b->sense);
542	
543	    if (err) {
544	        if (model) GRBfreemodel(model);
545	        varmap_free(m);
546	        return err;
547	    }
548	    *model_out = model;
549	    *map_out = m;
550	    return 0;
551	}
552	
553	void varmap_free(VarMap *m) {
554	    if (!m) return;
555	    for (int g = 0; g < m->ngen; g++) {
556	        free(m->gen[g].u); free(m->gen[g].v); free(m->gen[g].w);
557	        free(m->gen[g].pp); free(m->gen[g].pa);
558	    }
559	    free(m->gen);
560	    free(m->pw); free(m->splus); free(m->sminus); free(m->sr);
561	    free(m);
562	}
