178	static int load_gen(Instance *inst, Gen *g, const char *key, const JsonValue *jg,
179	                    char *err, unsigned long errlen) {
180	    g->name = xstrdup(key);
181	    const JsonValue *jn = json_get(jg, "name");
182	    if (jn && jn->type == JSON_STRING && strcmp(jn->string, key) != 0) inst->n_name_mismatch++;
183	    if (jg->type != JSON_OBJECT) return seterr(err, errlen, "%s: not an object", key);
184	
185	    int *r = &inst->n_int_rounded;
186	    if (!get_int(jg, "must_run", key, &g->must_run, r, err, errlen) ||
187	        !get_num(jg, "power_output_minimum", key, &g->pmin, err, errlen) ||
188	        !get_num(jg, "power_output_maximum", key, &g->pmax, err, errlen) ||
189	        !get_num(jg, "ramp_up_limit", key, &g->ru, err, errlen) ||
190	        !get_num(jg, "ramp_down_limit", key, &g->rd, err, errlen) ||
191	        !get_num(jg, "ramp_startup_limit", key, &g->su_raw, err, errlen) ||
192	        !get_num(jg, "ramp_shutdown_limit", key, &g->sd_raw, err, errlen) ||
193	        !get_int(jg, "time_up_minimum", key, &g->ut, r, err, errlen) ||
194	        !get_int(jg, "time_down_minimum", key, &g->dt, r, err, errlen) ||
195	        !get_int(jg, "unit_on_t0", key, &g->on0, r, err, errlen) ||
196	        !get_num(jg, "power_output_t0", key, &g->p0, err, errlen) ||
197	        !get_int(jg, "time_up_t0", key, &g->up0, r, err, errlen) ||
198	        !get_int(jg, "time_down_t0", key, &g->down0, r, err, errlen))
199	        return 0;
200	
201	    if (g->pmax < g->pmin) return seterr(err, errlen, "%s: maximum power is below minimum", key);
202	    if (g->ru <= 0 || g->rd <= 0) return seterr(err, errlen, "%s: ramp rates must be positive", key);
203	
204	    /* The formulation has no meaning for UT or DT below one period. */
205	    if (g->ut < 1) g->ut = 1;
206	    if (g->dt < 1) g->dt = 1;
207	
208	    /* A limit above Pbar never binds; clipping keeps Pbar-SU and Pbar-SD nonnegative. */
209	    g->su = g->su_raw < g->pmax ? g->su_raw : g->pmax;
210	    g->sd = g->sd_raw < g->pmax ? g->sd_raw : g->pmax;
211	
212	    g->tru = floor_ratio(g->pmax - g->su, g->ru);
213	    g->trd = floor_ratio(g->pmax - g->sd, g->rd);
214	
215	    g->need_up = g->on0 && g->ut > g->up0 ? g->ut - g->up0 : 0;
216	    g->need_down = !g->on0 && g->dt > g->down0 ? g->dt - g->down0 : 0;
217	
218	    return load_startup(inst, g, jg, err, errlen) && load_curve(inst, g, jg, err, errlen);
219	}
