1	/* uc_unitcheck [--variant NAME]... [--gens N] [--seeds K] instance.json
2	 *
3	 * Tests that formulation T's strengthened inequalities cut off no feasible schedule
4	 * and admit no infeasible one. For a single generator, with no system rows, it
5	 * optimizes the same random objective over T and over the basic physical model and
6	 * compares the integer optima; any difference is a bug in one of the two. */
7	#include "model.h"
8	
9	#include <math.h>
10	#include <stdio.h>
11	#include <stdlib.h>
12	#include <string.h>
13	
14	static double rnd(unsigned *state) {
15	    /* xorshift32, so results do not depend on the C library */
16	    unsigned x = *state;
17	    x ^= x << 13; x ^= x >> 17; x ^= x << 5;
18	    *state = x;
19	    return 2.0 * ((double)x / 4294967296.0) - 1.0;
20	}
21	
22	static int solve_one(GRBenv *env, const Instance *in, ModelOptions o, int gi, unsigned seed, double *val) {
23	    GRBmodel *model = NULL;
24	    VarMap *m = NULL;
25	    o.only_gen = gi;
26	    int err = model_build(env, in, &o, &model, &m);
27	    if (err) return err;
28	    int nv;
29	    GRBgetintattr(model, GRB_INT_ATTR_NUMVARS, &nv);
30	    for (int k = 0; k < nv; k++) GRBsetdblattrelement(model, GRB_DBL_ATTR_OBJ, k, 0.0);
31	    const Gen *g = &in->gen[gi];
32	    const GenVars *x = &m->gen[gi];
33	    double scale = g->pmax > 1 ? g->pmax : 1;
34	    unsigned s = seed;
35	    for (int t = 1; t <= in->T; t++) {
36	        /* Mostly push output and availability up, which is where a bad bound shows. */
37	        GRBsetdblattrelement(model, GRB_DBL_ATTR_OBJ, x->pp[t], rnd(&s) - 0.5);
38	        GRBsetdblattrelement(model, GRB_DBL_ATTR_OBJ, x->pa[t], rnd(&s) - 0.5);
