    if (have_objective) {
        double *x = malloc((size_t)numvars * sizeof *x);
        if (!x) { fprintf(stderr, "out of memory\n"); return 1; }
        CHECK(GRBgetdblattrarray(model, GRB_DBL_ATTR_X, 0, numvars, x));
        { /* TEMP DIAG: reserve row residual, raw and as written */
            extern int diag_duals;
            if (diag_duals) {
                double worst_raw = 0, worst_exact = 0, worst_csv = 0, max_sr = 0, max_frac = 0, worst_r = 0;
                int t_raw = 0, t_exact = 0, t_csv = 0, nviol_csv = 0, t_r = 0, n_r5 = 0, n_c5 = 0;
                for (int t = 1; t <= in->T; t++) {
                    double raw = x[map->pw[t]] + x[map->sr[t]], exact = x[map->pw[t]], csv = round(x[map->pw[t]] * 1e6) / 1e6;
                    double rform = 0;
