                        double power = nonneg(x[gv->pp[t]]) + in->gen[gi].pmin * on;
                        double avail = nonneg(x[gv->pa[t]]) + in->gen[gi].pmin * on;
                        if (avail < power) avail = power;
                        exact += avail;
                        csv += round(avail * 1e6) / 1e6;
                        rform += round(avail * 1e6) / 1e6 - round(power * 1e6) / 1e6;
                    }
                    double need = in->demand[t] + in->reserve[t];
                    if (in->reserve[t] - rform > worst_r) { worst_r = in->reserve[t] - rform; t_r = t; }
                    if (in->reserve[t] - rform > 1e-5) n_r5++;
                    if (need - csv > 1e-5) n_c5++;
                    if (x[map->sr[t]] > max_sr) max_sr = x[map->sr[t]];
                    if (need - raw > worst_raw) { worst_raw = need - raw; t_raw = t; }
                    if (need - exact > worst_exact) { worst_exact = need - exact; t_exact = t; }
                    if (need - csv > worst_csv) { worst_csv = need - csv; t_csv = t; }
                    if (need - csv > 1e-6) nviol_csv++;
                }
                fprintf(stderr, "reserve shortfall of row: raw %.3e (t=%d); rounded u %.3e (t=%d); as written %.3e (t=%d); periods above 1e-6 as written %d; max s_R %.3e; max |u-round(u)| %.3e\n",
                        worst_raw, t_raw, worst_exact, t_exact, worst_csv, t_csv, nviol_csv, max_sr, max_frac);
                fprintf(stderr, "as written, form avail-power>=R: worst %.3e (t=%d), periods above 1e-5: %d; form (67)+pW periods above 1e-5: %d\n",
                        worst_r, t_r, n_r5, n_c5);
            }
        }
        double shed = 0, over = 0, shortfall = 0, used = 0, avail = 0;
        for (int t = 1; t <= in->T; t++) {
            shed += x[map->splus[t]];
            over += x[map->sminus[t]];
            shortfall += x[map->sr[t]];
            used += x[map->pw[t]];
            avail += in->ren_max[t];
        }
        printf("load_shed_mwh=%.6f\nover_generation_mwh=%.6f\nreserve_shortfall_mwh=%.6f\n",
               shed, over, shortfall);
        printf("renewable_used_mwh=%.3f\nrenewable_available_mwh=%.3f\n", used, avail);
        if (solution) exit_code = write_solution(solution, in, map, x, opt.relax);
        free(x);
    } else {
        if (solution) fprintf(stderr, "no solution available; %s not written\n", solution);
        exit_code = 1;
    }

    varmap_free(map);
    GRBfreemodel(model);
    GRBfreeenv(env);
    instance_free(in);
    return exit_code;
}

